    expect(body).toContain('helpers-source-merged');
    expect(body).toContain('beyond-post226');
    expect(body).toContain('wrangler-ci-merged');
    expect(body).toContain('after-#233');
    expect(body.includes(['describe(', "'post236 parser"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post236 routes"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post236 wrangler"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post236 ci-config"].join(''))).toBe(false);
