  it('post236-extras: utf16le-bytes src/genres.ts', () => { expect(Buffer.byteLength(read("src/genres.ts"), 'utf16le')).toBe(2050); });
  it('post236-extras: nibble src/genres.ts', () => { expect(nibbleSum(sha256("src/genres.ts"))).toBe(500); });
  it('post236-extras: pairSum src/genres.ts', () => { const hex=sha256("src/genres.ts"); let s=0; for(let i=0;i<hex.length;i+=2) s+=parseInt(hex.slice(i,i+2),16); expect(s).toBe(3950); });
  it('post236-extras: rollingXor src/genres.ts', () => { const hex=sha256("src/genres.ts"); let a=0; for(let i=0;i<hex.length;i+=2) a^=parseInt(hex.slice(i,i+2),16); expect(a).toBe(96); });
