    expect(read(['test', 'routes.test.ts'].join('/')).includes(['describe(', "'post251 mcp-spec-contract HEAVY deepen"].join(''))).toBe(false);
    expect(read("test/genres.test.ts").includes(['describe(', "'post251 mcp-spec-contract HEAVY deepen"].join(''))).toBe(false);
