    expect(body).toContain('wrangler-ci-merged-263');
    expect(body).toContain('media-parser-merged-262');
    expect(body).toContain('morning-leftover');
    expect(body).toContain('dual-surface');
    expect(body).toContain('tip-261');
    expect(body.includes(['describe(', "'post261 parser"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post261 wrangler"].join(''))).toBe(false);
    expect(body.includes(['describe(', "'post261 helpers"].join(''))).toBe(false);
